Here's the complete account settings screen. It follows platform HIG/Material guidance pulled from the aura-uiux skill: 48×48dp/44×44pt minimum touch targets, native `Alert` for the destructive confirmation (renders as a proper two-button alert on iOS and a Material dialog on Android, each honoring its own destructive-button convention), a dark-mode elevation ladder where nearer surfaces get *lighter* rather than shadowed, safe-area-aware layout, and Dynamic Type-friendly rows (`minHeight` instead of fixed `height`, no truncation of the destructive label).

```tsx
// AccountSettingsScreen.tsx
// Dependencies: react, react-native, react-native-safe-area-context
import React, { useCallback, useMemo, useState } from 'react';
import {
  View,
  Text,
  ScrollView,
  Pressable,
  Switch,
  Image,
  Alert,
  ActivityIndicator,
  StyleSheet,
  Platform,
  useColorScheme,
  StatusBar,
} from 'react-native';
import { SafeAreaView, useSafeAreaInsets } from 'react-native-safe-area-context';

// ---------------------------------------------------------------------------
// Tokens — semantic, not raw hex in components. Dark tiers get lighter (not
// shadowed) as they sit nearer the user, per the Material/HIG elevation ladder.
// bg.app avoids pure black so large dark areas don't look like a hole.
// ---------------------------------------------------------------------------

type Tokens = {
  bgApp: string;
  bgSurface: string;
  bgSurfaceRaised: string;
  border: string;
  textPrimary: string;
  textMuted: string;
  accent: string;
  danger: string;
  dangerSurface: string;
  onAccent: string;
  overlayPressed: string;
};

const lightTokens: Tokens = {
  bgApp: '#F2F2F7',
  bgSurface: '#FFFFFF',
  bgSurfaceRaised: '#FFFFFF',
  border: '#E1E1E6',
  textPrimary: '#1C1C1E',
  textMuted: '#6B6B70',
  accent: '#0A84FF',
  danger: '#D70015',
  dangerSurface: '#FDEDEC',
  onAccent: '#FFFFFF',
  overlayPressed: 'rgba(60,60,67,0.08)',
};

const darkTokens: Tokens = {
  bgApp: '#0B0B0D',
  bgSurface: '#1C1C1E',
  bgSurfaceRaised: '#242428',
  border: '#38383A',
  textPrimary: '#F2F2F7',
  textMuted: '#9B9BA1',
  accent: '#409CFF',
  danger: '#FF6961',
  dangerSurface: '#2A1715',
  onAccent: '#0B0B0D',
  overlayPressed: 'rgba(255,255,255,0.08)',
};

// Satisfies both platform floors: iOS wants 44pt, Android wants 48dp.
const MIN_TOUCH_TARGET = 48;

// ---------------------------------------------------------------------------
// Data model for the settings list
// ---------------------------------------------------------------------------

interface NavRow {
  type: 'nav';
  key: string;
  label: string;
  value?: string;
  onPress: () => void;
}

interface ToggleRow {
  type: 'toggle';
  key: string;
  label: string;
  value: boolean;
  onValueChange: (next: boolean) => void;
}

interface DestructiveRow {
  type: 'destructive';
  key: string;
  label: string;
  onPress: () => void;
  busy?: boolean;
}

type SettingsRowConfig = NavRow | ToggleRow | DestructiveRow;

interface SettingsSection {
  title?: string;
  rows: SettingsRowConfig[];
}

// ---------------------------------------------------------------------------
// Public props
// ---------------------------------------------------------------------------

export interface AccountSettingsScreenProps {
  profile: {
    name: string;
    email: string;
    avatarUrl?: string;
  };
  onBack?: () => void;
  onEditProfile: () => void;
  onChangePassword: () => void;
  onPrivacyPress: () => void;
  onLanguagePress: () => void;
  onHelpPress: () => void;
  onLogout: () => void;
  /** Reject to signal failure; the screen shows an error alert and stays put. */
  onDeleteAccount: () => Promise<void>;
}

export default function AccountSettingsScreen({
  profile,
  onBack,
  onEditProfile,
  onChangePassword,
  onPrivacyPress,
  onLanguagePress,
  onHelpPress,
  onLogout,
  onDeleteAccount,
}: AccountSettingsScreenProps) {
  const scheme = useColorScheme();
  const tokens = scheme === 'dark' ? darkTokens : lightTokens;
  const styles = useMemo(() => createStyles(tokens), [tokens]);
  const insets = useSafeAreaInsets();

  const [pushNotifications, setPushNotifications] = useState(true);
  const [biometricLogin, setBiometricLogin] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const confirmDelete = useCallback(() => {
    Alert.alert(
      'Delete account?',
      'This permanently deletes your account and all of your data. This can\u2019t be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete Account',
          style: 'destructive',
          onPress: async () => {
            setIsDeleting(true);
            try {
              await onDeleteAccount();
            } catch (err) {
              Alert.alert(
                'Couldn\u2019t delete account',
                err instanceof Error ? err.message : 'Please try again.',
              );
            } finally {
              setIsDeleting(false);
            }
          },
        },
      ],
      { cancelable: true },
    );
  }, [onDeleteAccount]);

  const sections: SettingsSection[] = [
    {
      title: 'Preferences',
      rows: [
        {
          type: 'toggle',
          key: 'push',
          label: 'Push Notifications',
          value: pushNotifications,
          onValueChange: setPushNotifications,
        },
        {
          type: 'toggle',
          key: 'biometric',
          label: Platform.OS === 'ios' ? 'Face ID & Touch ID' : 'Biometric Login',
          value: biometricLogin,
          onValueChange: setBiometricLogin,
        },
        {
          type: 'nav',
          key: 'language',
          label: 'Language',
          value: 'English',
          onPress: onLanguagePress,
        },
      ],
    },
    {
      title: 'Security',
      rows: [
        {
          type: 'nav',
          key: 'password',
          label: 'Change Password',
          onPress: onChangePassword,
        },
        {
          type: 'nav',
          key: 'privacy',
          label: 'Privacy',
          onPress: onPrivacyPress,
        },
      ],
    },
    {
      title: 'Support',
      rows: [
        { type: 'nav', key: 'help', label: 'Help & Support', onPress: onHelpPress },
        { type: 'nav', key: 'logout', label: 'Log Out', onPress: onLogout },
      ],
    },
    {
      title: 'Danger Zone',
      rows: [
        {
          type: 'destructive',
          key: 'delete',
          label: 'Delete Account',
          onPress: confirmDelete,
          busy: isDeleting,
        },
      ],
    },
  ];

  return (
    <SafeAreaView style={styles.safeArea} edges={['top', 'left', 'right']}>
      <StatusBar barStyle={scheme === 'dark' ? 'light-content' : 'dark-content'} />
      <View style={styles.header}>
        {onBack ? (
          <Pressable
            onPress={onBack}
            hitSlop={12}
            accessibilityRole="button"
            accessibilityLabel="Go back"
            style={({ pressed }) => [
              styles.backButton,
              pressed && Platform.OS === 'ios' && { opacity: 0.5 },
            ]}
            android_ripple={{ color: tokens.overlayPressed, radius: 20 }}
          >
            <Text style={styles.backGlyph}>{'\u2039'}</Text>
          </Pressable>
        ) : (
          <View style={styles.backButton} />
        )}
        <Text style={styles.headerTitle} numberOfLines={1}>
          Account
        </Text>
        <View style={styles.backButton} />
      </View>

      <ScrollView
        contentContainerStyle={[styles.scrollContent, { paddingBottom: insets.bottom + 24 }]}
        showsVerticalScrollIndicator={false}
      >
        <Pressable
          onPress={onEditProfile}
          accessibilityRole="button"
          accessibilityLabel={`Edit profile, ${profile.name}`}
          style={({ pressed }) => [
            styles.profileRow,
            pressed && Platform.OS === 'ios' && { opacity: 0.7 },
          ]}
          android_ripple={{ color: tokens.overlayPressed }}
        >
          {profile.avatarUrl ? (
            <Image source={{ uri: profile.avatarUrl }} style={styles.avatar} />
          ) : (
            <View style={[styles.avatar, styles.avatarFallback]}>
              <Text style={styles.avatarInitials}>{getInitials(profile.name)}</Text>
            </View>
          )}
          <View style={styles.profileText}>
            <Text style={styles.profileName} numberOfLines={1}>
              {profile.name}
            </Text>
            <Text style={styles.profileEmail} numberOfLines={1}>
              {profile.email}
            </Text>
          </View>
          <Text style={styles.chevron}>{'\u203A'}</Text>
        </Pressable>

        {sections.map((section) => (
          <View key={section.title ?? section.rows[0].key} style={styles.section}>
            {section.title ? <Text style={styles.sectionTitle}>{section.title}</Text> : null}
            <View style={styles.sectionBody}>
              {section.rows.map((row, index) => (
                <React.Fragment key={row.key}>
                  <SettingsRow row={row} tokens={tokens} styles={styles} />
                  {index < section.rows.length - 1 ? <View style={styles.divider} /> : null}
                </React.Fragment>
              ))}
            </View>
          </View>
        ))}
      </ScrollView>
    </SafeAreaView>
  );
}

// ---------------------------------------------------------------------------
// Row renderer
// ---------------------------------------------------------------------------

function SettingsRow({
  row,
  tokens,
  styles,
}: {
  row: SettingsRowConfig;
  tokens: Tokens;
  styles: ReturnType<typeof createStyles>;
}) {
  if (row.type === 'toggle') {
    return (
      <View style={styles.row} accessibilityRole="none">
        <Text style={styles.rowLabel}>{row.label}</Text>
        <Switch
          value={row.value}
          onValueChange={row.onValueChange}
          accessibilityRole="switch"
          accessibilityLabel={row.label}
          trackColor={{ false: tokens.border, true: tokens.accent }}
        />
      </View>
    );
  }

  if (row.type === 'destructive') {
    return (
      <Pressable
        onPress={row.busy ? undefined : row.onPress}
        disabled={row.busy}
        accessibilityRole="button"
        accessibilityLabel={row.label}
        accessibilityState={{ disabled: row.busy }}
        style={({ pressed }) => [
          styles.row,
          pressed && Platform.OS === 'ios' && !row.busy && { opacity: 0.6 },
          row.busy && { opacity: 0.6 },
        ]}
        android_ripple={{ color: tokens.overlayPressed }}
      >
        <Text style={[styles.rowLabel, styles.destructiveLabel]}>{row.label}</Text>
        {row.busy ? <ActivityIndicator color={tokens.danger} /> : null}
      </Pressable>
    );
  }

  return (
    <Pressable
      onPress={row.onPress}
      accessibilityRole="button"
      accessibilityLabel={row.value ? `${row.label}, ${row.value}` : row.label}
      style={({ pressed }) => [styles.row, pressed && Platform.OS === 'ios' && { opacity: 0.6 }]}
      android_ripple={{ color: tokens.overlayPressed }}
    >
      <Text style={styles.rowLabel} numberOfLines={1}>
        {row.label}
      </Text>
      <View style={styles.rowTrailing}>
        {row.value ? (
          <Text style={styles.rowValue} numberOfLines={1}>
            {row.value}
          </Text>
        ) : null}
        <Text style={styles.chevron}>{'\u203A'}</Text>
      </View>
    </Pressable>
  );
}

function getInitials(name: string): string {
  return name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? '')
    .join('');
}

// ---------------------------------------------------------------------------
// Styles
// ---------------------------------------------------------------------------

function createStyles(tokens: Tokens) {
  return StyleSheet.create({
    safeArea: {
      flex: 1,
      backgroundColor: tokens.bgApp,
    },
    header: {
      flexDirection: 'row',
      alignItems: 'center',
      justifyContent: 'space-between',
      paddingHorizontal: 4,
      minHeight: MIN_TOUCH_TARGET,
    },
    backButton: {
      width: MIN_TOUCH_TARGET,
      height: MIN_TOUCH_TARGET,
      alignItems: 'center',
      justifyContent: 'center',
    },
    backGlyph: {
      fontSize: 28,
      color: tokens.accent,
    },
    headerTitle: {
      flex: 1,
      textAlign: 'center',
      fontSize: 17,
      fontWeight: '600',
      color: tokens.textPrimary,
    },
    scrollContent: {
      paddingHorizontal: 16,
      paddingTop: 8,
    },
    profileRow: {
      flexDirection: 'row',
      alignItems: 'center',
      backgroundColor: tokens.bgSurface,
      borderRadius: 14,
      padding: 14,
      minHeight: 72,
      gap: 12,
    },
    avatar: {
      width: 56,
      height: 56,
      borderRadius: 28,
    },
    avatarFallback: {
      backgroundColor: tokens.accent,
      alignItems: 'center',
      justifyContent: 'center',
    },
    avatarInitials: {
      color: tokens.onAccent,
      fontSize: 20,
      fontWeight: '600',
    },
    profileText: {
      flex: 1,
      gap: 2,
    },
    profileName: {
      fontSize: 17,
      fontWeight: '600',
      color: tokens.textPrimary,
    },
    profileEmail: {
      fontSize: 14,
      color: tokens.textMuted,
    },
    section: {
      marginTop: 24,
    },
    sectionTitle: {
      fontSize: 13,
      fontWeight: '600',
      color: tokens.textMuted,
      textTransform: 'uppercase',
      letterSpacing: 0.4,
      marginBottom: 8,
      marginLeft: 4,
    },
    sectionBody: {
      backgroundColor: tokens.bgSurface,
      borderRadius: 14,
      overflow: 'hidden',
    },
    row: {
      flexDirection: 'row',
      alignItems: 'center',
      justifyContent: 'space-between',
      minHeight: MIN_TOUCH_TARGET,
      paddingHorizontal: 14,
      paddingVertical: 10,
      gap: 12,
    },
    rowLabel: {
      flex: 1,
      fontSize: 16,
      color: tokens.textPrimary,
    },
    destructiveLabel: {
      color: tokens.danger,
      fontWeight: '500',
    },
    rowTrailing: {
      flexDirection: 'row',
      alignItems: 'center',
      gap: 6,
    },
    rowValue: {
      fontSize: 15,
      color: tokens.textMuted,
    },
    chevron: {
      fontSize: 20,
      color: tokens.textMuted,
    },
    divider: {
      height: 1,
      backgroundColor: tokens.border,
      marginLeft: 14,
    },
  });
}
```

Notes on the choices, in case you want to deviate:

- **`Alert.alert` for the delete confirmation** — it already renders as a native two-button alert (iOS) / Material dialog (Android), each with the platform's own destructive-button convention, so it satisfies "max two actions" on Android and the destructive-style/separate-Cancel rule on iOS without hand-building two different components.
- **`minHeight`, not `height`**, on every row — so Dynamic Type / larger Android font scales can grow the row instead of clipping text.
- **Dark palette avoids pure black** for `bg.app` and uses lighter (not shadowed) tones for nearer surfaces, per the Material/HIG elevation ladder.
- Swap the `\u2039`/`\u203A` glyphs for your icon library of choice (e.g. `@expo/vector-icons`) — kept as text here to avoid an extra dependency in a single-file sample.
- Wire `profile`, the six callback props, and `onDeleteAccount` (should reject on failure) to your actual navigation/auth logic.
